$sourcePublic=$pub('source');$url='https://example.com/'.$run.'/entities';$pdo->prepare("INSERT INTO sources(public_id,source_type,canonical_url,canonical_url_hash,domain,title,status) VALUES(?,'webpage',?,?,?,'Entity source','current')")->execute([$sourcePublic,$url,hash('sha256',$url),'example.com']);$sourceId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash) VALUES(?,1,?,'Entity V1','Alice works at Acme in Phoenix.',?)")->execute([$sourceId,$url,hash('sha256','Alice works at Acme in Phoenix.')]);$v1=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$v1,$sourceId]);$pdo->prepare('INSERT INTO project_sources(project_id,source_id,added_by_user_id) VALUES(?,?,?)')->execute([$projectId,$sourceId,$owner['id']]);
$capturePublic=$pub('capture');$pdo->prepare("INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text) VALUES(?,?,?,?,'text','Alice works at Acme')")->execute([$capturePublic,$sourceId,$v1,$owner['id']]);$captureId=(int)$pdo->lastInsertId();$annotationPublic=$pub('annotation');$pdo->prepare("INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,visibility,status) VALUES(?,?,?,?,?,'Employment reference','private','published')")->execute([$annotationPublic,$owner['id'],$sourceId,$v1,$captureId]);$annotationId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO project_annotations(project_id,annotation_id,added_by_user_id) VALUES(?,?,?)')->execute([$projectId,$annotationId,$owner['id']]);
$claimPublic=$pub('claim');$pdo->prepare("INSERT INTO research_claims(public_id,project_id,created_by_user_id,statement,claim_type,status) VALUES(?,?,?,'Alice works at Acme.','factual','supported')")->execute([$claimPublic,$projectId,$owner['id']]);$claimId=(int)$pdo->lastInsertId();$findingPublic=$pub('finding');$pdo->prepare("INSERT INTO research_findings(public_id,project_id,created_by_user_id,title,summary,status) VALUES(?,?,?,'Employment finding','Project evidence associates Alice with Acme.','final')")->execute([$findingPublic,$projectId,$owner['id']]);$findingId=(int)$pdo->lastInsertId();
$alice=research_entity_upsert($pdo,$projectId,$owner['id'],'Alice Example','person','Person named in project evidence','manual');re_ok($alice['status']==='confirmed','Manual entity was not confirmed.');$acme=research_entity_upsert($pdo,$projectId,$owner['id'],'Acme Corp','company','Company named in project evidence','manual');$other=research_entity_upsert($pdo,$project2Id,$owner['id'],'Other Org','organization',null,'manual');
$ownerEntity=research_entity_access($pdo,$owner,$alice['public_id']);$viewerEntity=research_entity_access($pdo,$viewer,$alice['public_id']);$outsiderEntity=research_entity_access($pdo,$outsider,$alice['public_id']);re_ok($ownerEntity!==null&&project_can_write($ownerEntity),'Owner cannot write Entity.');re_ok($viewerEntity!==null&&!project_can_write($viewerEntity),'Viewer gained Entity write access.');re_ok($outsiderEntity===null,'Entity leaked outside project.');re_ok(research_project_entity_target($pdo,$projectId,$other['public_id'])===null,'Entity resolver crossed project boundary.');
re_ok(research_entity_attach_reference($pdo,$projectId,$alice['id'],$owner['id'],'source_version',$sourcePublic,'Pinned source'),'Source reference failed.');re_ok(research_entity_attach_reference($pdo,$projectId,$alice['id'],$owner['id'],'annotation',$annotationPublic,'Pinned annotation'),'Annotation reference failed.');re_ok(research_entity_attach_reference($pdo,$projectId,$alice['id'],$owner['id'],'claim',$claimPublic),'Claim reference failed.');re_ok(research_entity_attach_reference($pdo,$projectId,$alice['id'],$owner['id'],'finding',$findingPublic),'Finding reference failed.');re_ok(!research_entity_attach_reference($pdo,$projectId,$alice['id'],$owner['id'],'claim',$pub('missing')),'Invented project reference was accepted.');
$pdo->prepare("INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash) VALUES(?,2,?,'Entity V2','Alice no longer appears.',?)")->execute([$sourceId,$url,hash('sha256','Alice no longer appears.')]);$v2=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE sources SET current_version_id=? WHERE id=?')->execute([$v2,$sourceId]);$mentions=research_entity_mentions($pdo,$projectId,$alice['id']);$versionMentions=array_values(array_filter($mentions,fn($m)=>in_array($m['mention_type'],['source_version','annotation'],true)));foreach($versionMentions as $m)re_ok((int)$m['source_version_id']===$v1,'Entity reference drifted to newer Source Version.');
$pdo->prepare('DELETE FROM annotations WHERE id=?')->execute([$annotationId]);$q=$pdo->prepare("SELECT annotation_id,source_version_id FROM research_entity_mentions WHERE entity_id=? AND mention_type='annotation' LIMIT 1");$q->execute([$alice['id']]);$surviving=$q->fetch();re_ok($surviving!==false&&$surviving['annotation_id']===null&&(int)$surviving['source_version_id']===$v1,'Entity provenance did not survive Annotation deletion.');
$relationPublic=$pub('erel');$pdo->prepare("INSERT INTO research_entity_relations(public_id,project_id,source_entity_id,target_entity_id,added_by_user_id,relation_type,note) VALUES(?,?,?,?,?,'works_for','CI relationship')")->execute([$relationPublic,$projectId,$alice['id'],$acme['id'],$owner['id']]);re_throws(fn()=>$pdo->prepare("INSERT INTO research_entity_relations(public_id,project_id,source_entity_id,target_entity_id,added_by_user_id,relation_type) VALUES(?,?,?,?,?,'related_to')")->execute([$pub('cross'),$projectId,$alice['id'],$other['id'],$owner['id']]),'Cross-project Entity relation was accepted.');re_throws(fn()=>$pdo->prepare("INSERT INTO research_entity_relations(public_id,project_id,source_entity_id,target_entity_id,added_by_user_id,relation_type) VALUES(?,?,?,?,?,'related_to')")->execute([$pub('self'),$projectId,$alice['id'],$alice['id'],$owner['id']]),'Self Entity relation was accepted.');
$aiData=['entities'=>[['name'=>'Phoenix','type'=>'place','description'=>'Place extracted from project','refs'=>[['type'=>'SOURCE','id'=>$sourcePublic],['type'=>'CLAIM','id'=>$claimPublic],['type'=>'SOURCE','id'=>$pub('invented')]]]],'relationships'=>[['source'=>'Alice Example','source_type'=>'person','relation'=>'associated_with','target'=>'Phoenix','target_type'=>'place','note'=>'AI suggestion']]];$applied=research_apply_ai_entities($pdo,$projectId,$owner['id'],$aiData,$pub('airun'));re_ok($applied['entities']===1,'AI entity suggestion was not created.');$q=$pdo->prepare("SELECT * FROM research_entities WHERE project_id=? AND entity_type='place' AND normalized_name=?");$q->execute([$projectId,research_entity_normalized_name('Phoenix')]);$phoenix=$q->fetch();re_ok($phoenix!==false&&$phoenix['status']==='suggested'&&$phoenix['source_type']==='ai','AI extraction did not remain Suggested.');$phoenixMentions=research_entity_mentions($pdo,$projectId,(int)$phoenix['id']);re_ok(count($phoenixMentions)===2,'AI extraction stored an invalid or missing project reference.');research_entity_upsert($pdo,$projectId,$owner['id'],'Phoenix','place','Confirmed by researcher','manual');$q=$pdo->prepare('SELECT status FROM research_entities WHERE id=?');$q->execute([$phoenix['id']]);re_ok($q->fetchColumn()==='confirmed','Manual review did not confirm AI entity.');
